Lemma shr_fexp_Z : forall p em m e l, 0 <= m ->
  let n := fexp p em (Zdigits2 m + e) - e in
  let '(mrs, e') := shr_fexp p em m e l in
  0 <= shr_m mrs /\ (n <= 0 -> shr_m mrs = m /\ e' = e) /\
  (0 < n -> e' = e + n /\ 2 ^ n * shr_m mrs <= m < 2 ^ n * (shr_m mrs + 1)).
