(* [comment removed for export] *)
Definition FBd (f : format) (k x : Z) : Prop :=
  match fp_decode f x with
  | S754_zero _ => True
  | S754_finite s m e => s = false /\ Zdigits2 (Z.pos m) + e <= k
  | _ => False
  end.
(* [comment removed for export] *)
Definition FB (f : format) (k x : Z) : Prop := 0 <= x < 2 ^ fp_width f /\ FBd f k x.

