(* [comment removed for export] *)
Lemma scaled_add_bound : forall ma ea mb eb K, 0 <= ma -> 0 <= mb ->
  (ma = 0 \/ Zdigits2 ma + ea <= K) -> (mb = 0 \/ Zdigits2 mb + eb <= K) ->
  0 <= fst (scaled_add (ma, ea) (mb, eb)) /\
  (fst (scaled_add (ma, ea) (mb, eb)) = 0 \/
