Lemma fb_add : forall md ka kb a b, FB f ka a -> FB f kb b -> fp_emin f <= Z.max ka kb + 1 -> Z.max ka kb + 2 <= fp_emax f ->
  FB f (Z.max ka kb + 2) (fst (fp_add f md a b)).
