Lemma fb_fma : forall md ka kb kc a b c, FB f ka a -> FB f kb b -> FB f kc c ->
  fp_emin f <= Z.max (ka + kb) kc + 1 -> Z.max (ka + kb) kc + 2 <= fp_emax f ->
  FB f (Z.max (ka + kb) kc + 2) (fst (fp_fma f md a b c)).
